const props=defineProps({event:Object,photo:Object,viewer:Object}),preferences=usePage().props.preferences||{}
const scale=ref(1),baseFitScale=ref(1),fitWidth=ref(0),fitHeight=ref(0),x=ref(0),y=ref(0),playing=ref(false),loop=ref(localStorage.getItem('lenspic:slideshow-loop')===null?Boolean(preferences.slideshow_loop):localStorage.getItem('lenspic:slideshow-loop')==='1'),controls=ref(true),infoOpen=ref(false),shareOpen=ref(false),deleteOpen=ref(false),busy=ref(false),sharing=ref(false),downloading=ref(false),message=ref(''),stage=ref(null),imageStage=ref(null),image=ref(null),imageReady=ref(false),interacting=ref(false),dragging=ref(false),animating=ref(false),tabVisible=ref(!document.hidden)
const shareData=ref(props.event.share)
let timer=null,hideTimer,gesture=null,lastTap=0,navigating=false,imageSafetyTimer=null,gestureAnimationTimer=null,fitObserver=null,closing=false,previousBodyOverflow='',fullscreenActive=false,suppressClick=false
const transform=computed(()=>`translate3d(${x.value}px,${y.value}px,0) scale(${scale.value})`)
const imageTransition=computed(()=>animating.value?'transform 180ms cubic-bezier(.22,.61,.36,1)':'none')
const imageCursor=computed(()=>dragging.value?'grabbing':scale.value>1?'move':'grab')
const size=computed(()=>props.photo.file_size?`${(props.photo.file_size/1048576).toFixed(1)} MB`:null)
function activity(){controls.value=true;clearTimeout(hideTimer);if(!infoOpen.value&&!shareOpen.value&&!deleteOpen.value)hideTimer=setTimeout(()=>controls.value=false,2800)}
const suspended=computed(()=>!tabVisible.value||!imageReady.value||interacting.value||infoOpen.value||shareOpen.value||deleteOpen.value)
function clearSlideshowTimer(){if(timer!==null){clearTimeout(timer);timer=null}}
function withIntent(url){if(!url)return null;const target=new URL(url,location.origin);if(playing.value)target.searchParams.set('slideshow','1');else target.searchParams.delete('slideshow');return target.href}
function navigate(url){if(navigating||closing)return;const target=withIntent(url);if(!target)return;navigating=true;clearSlideshowTimer();router.visit(target,{replace:true,preserveScroll:true,onError:()=>{navigating=false;playing.value=false;clearSlideshowTimer()}})}
function cancelGesture(){if(gesture?.target?.hasPointerCapture?.(gesture.pointerId))try{gesture.target.releasePointerCapture(gesture.pointerId)}catch{}gesture=null;dragging.value=false;interacting.value=false;animating.value=false;clearTimeout(gestureAnimationTimer);gestureAnimationTimer=null;document.documentElement.style.removeProperty('cursor')}
function cleanup(){playing.value=false;clearSlideshowTimer();clearTimeout(imageSafetyTimer);clearTimeout(hideTimer);cancelGesture();fitObserver?.disconnect();fitObserver=null;x.value=0;y.value=0;document.body.style.overflow=previousBodyOverflow;window.removeEventListener('keydown',keydown);window.removeEventListener('resize',measureFit);document.removeEventListener('visibilitychange',visibilityChanged);document.removeEventListener('fullscreenchange',fullscreenChanged)}
async function close(){if(closing)return;closing=true;cleanup();try{if(document.fullscreenElement)await document.exitFullscreen()}catch{}finally{let saved=null;try{saved=JSON.parse(sessionStorage.getItem(`lenspic:gallery:${props.event.id}`)||'null')}catch{}if(saved?.photoId&&history.length>1)history.back();else router.visit(props.event.gallery_url,{replace:true,preserveScroll:true,onError:()=>closing=false})}}
function zoom(delta){interacting.value=true;scale.value=Math.min(5,Math.max(1,scale.value+delta));if(scale.value===1){x.value=0;y.value=0}else nextTick(constrainPan);activity();setTimeout(()=>interacting.value=false,350)}
function reset(){cancelGesture();scale.value=1;x.value=0;y.value=0}
function scheduleSlideshow(){clearSlideshowTimer();if(!playing.value||suspended.value)return;const target=props.viewer.next_url||(loop.value?props.viewer.first_url:null);if(!target){playing.value=false;message.value='Slideshow finished';return}timer=setTimeout(()=>{timer=null;navigate(target)},Math.max(2,Math.min(20,Number(preferences.slideshow_interval||5)))*1000)}
function toggleSlideshow(){playing.value=!playing.value;scheduleSlideshow()}
function measureFit(resetPosition=false){if(!imageStage.value||!image.value?.naturalWidth||!image.value?.naturalHeight)return;const availableWidth=imageStage.value.clientWidth,availableHeight=imageStage.value.clientHeight,widthScale=availableWidth/image.value.naturalWidth,heightScale=availableHeight/image.value.naturalHeight,nextFit=Math.min(widthScale,heightScale);baseFitScale.value=nextFit;fitWidth.value=Math.max(1,Math.round(image.value.naturalWidth*nextFit));fitHeight.value=Math.max(1,Math.round(image.value.naturalHeight*nextFit));if(resetPosition||scale.value===1){x.value=0;y.value=0}else nextTick(constrainPan)}
function imageLoaded(){clearTimeout(imageSafetyTimer);measureFit(true);imageReady.value=true;scheduleSlideshow()}
function imageFailed(){clearTimeout(imageSafetyTimer);imageReady.value=true;scheduleSlideshow()}
async function favourite(){if(busy.value)return;const was=props.photo.liked,count=props.photo.likes_count;props.photo.liked=!was;props.photo.likes_count=Math.max(0,count+(props.photo.liked?1:-1));busy.value=true;try{const response=await fetch(`/groups/${props.event.id}/photos/${props.photo.id}/favourite`,{method:props.photo.liked?'POST':'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}});if(!response.ok)throw new Error();const data=await response.json();props.photo.liked=data.is_favourite;props.photo.likes_count=data.favourites_count;message.value=data.message}catch{props.photo.liked=was;props.photo.likes_count=count;message.value='Could not update favourites.'}finally{busy.value=false;setTimeout(()=>message.value='',2200)}}
function groupShareText(){const share=shareData.value,lines=[`View “${props.event.name}” on LensPic.`,'',`Open Group:\n${share.url}`];if(share.access_code)lines.push('',`Access code: ${share.access_code}`);if(share.expires_at)lines.push(`Expires: ${new Date(share.expires_at).toLocaleString()}`);return lines.join('\n')}
function shareFailureMessage(error){if(error?.status===401||error?.status===403)return'You do not have permission to share this Group.';if(error?.status===404)return'The Group no longer exists.';if(error?.status===409)return'Group sharing is currently disabled.';if(error?.status===419)return'Your session expired. Refresh the page and try again.';return'The invitation link could not be created. Please try again.'}
async function authorizedGroupShare(){if(shareData.value?.url)return shareData.value;if(!shareData.value?.endpoint){const error=new Error('Sharing is unavailable.');error.status=403;throw error}const response=await fetch(shareData.value.endpoint,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}});if(!response.ok){const error=new Error('Share request failed');error.status=response.status;throw error}shareData.value=await response.json();return shareData.value}
async function shareCurrentGroup(){if(sharing.value||!props.event.can_share_group)return;sharing.value=true;activity();try{const authorized=await authorizedGroupShare(),data={title:props.event.name,text:`View ${props.event.name} on LensPic`,url:authorized.url};if(!navigator.share){shareOpen.value=true;return}try{await navigator.share(data);message.value='Group shared.'}catch(error){if(error?.name!=='AbortError')message.value='The Group could not be shared.'}}catch(error){message.value=shareFailureMessage(error)}finally{sharing.value=false;setTimeout(()=>message.value='',2600)}}
async function copyLink(){try{await navigator.clipboard.writeText(shareData.value.url);message.value='Group link copied.';shareOpen.value=false}catch{message.value='Select and copy the Group link below.'}finally{setTimeout(()=>message.value='',2600)}}
function shareWhatsApp(){const anchor=document.createElement('a');anchor.href=`https://wa.me/?text=${encodeURIComponent(groupShareText())}`;anchor.target='_blank';anchor.rel='noopener noreferrer';anchor.click()}
function downloadCurrentPhoto(){if(downloading.value||!props.photo.download_url)return;const downloadUrl=props.photo.download_url,filename=(props.photo.original_filename||`lenspic-photo-${props.photo.id}.jpg`).replace(/[\\/]/g,'-'),anchor=document.createElement('a');downloading.value=true;anchor.href=downloadUrl;anchor.download=filename;anchor.hidden=true;document.body.appendChild(anchor);anchor.click();anchor.remove();message.value='Download started';setTimeout(()=>{downloading.value=false;message.value=''},1200)}
async function remove(){busy.value=true;try{const response=await fetch(`/groups/${props.event.id}/photos/${props.photo.id}`,{method:'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}});if(!response.ok)throw new Error();router.visit(props.viewer.next_url||props.viewer.previous_url||props.event.gallery_url)}catch{message.value='Could not delete this photo.';deleteOpen.value=false}finally{busy.value=false}}
async function fullscreen(){try{document.fullscreenElement?await document.exitFullscreen():await stage.value?.requestFullscreen()}catch{message.value='Fullscreen is unavailable.'}}
function keydown(e){if(e.key==='Tab'){const nodes=[...stage.value.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(node=>node.offsetParent!==null);if(nodes.length){const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;activity();if(e.key==='Escape'){e.preventDefault();close()}else if(e.key==='ArrowLeft')navigate(props.viewer.previous_url);else if(e.key==='ArrowRight')navigate(props.viewer.next_url);else if(['+','='].includes(e.key))zoom(.25);else if(e.key==='-')zoom(-.25);else if(e.key==='0')reset();else if(e.key===' '){e.preventDefault();toggleSlideshow()}else if(e.key.toLowerCase()==='f'&&props.event.favourites_enabled)favourite();else if(e.key.toLowerCase()==='d'&&props.photo.download_url){e.preventDefault();downloadCurrentPhoto()}}
function wheel(e){e.preventDefault();zoom(e.deltaY<0?.2:-.2)}
function panBounds(){if(!imageStage.value||!fitWidth.value||!fitHeight.value)return{x:0,y:0};const viewerWidth=imageStage.value.clientWidth,viewerHeight=imageStage.value.clientHeight,scaledWidth=fitWidth.value*scale.value,scaledHeight=fitHeight.value*scale.value;return{x:scale.value>1?Math.abs(viewerWidth-scaledWidth)/2:0,y:Math.abs(viewerHeight-scaledHeight)/2}}
function clamp(value,min,max){return Math.min(max,Math.max(min,value))}
