function pointerDown(e){if(e.button!==undefined&&e.button!==0)return;if(navigating||animating.value||!imageReady.value)return;interacting.value=true;dragging.value=false;clearSlideshowTimer();gesture={pointerId:e.pointerId,target:e.currentTarget,startX:e.clientX,startY:e.clientY,lastX:e.clientX,lastTime:performance.now(),velocityX:0,originX:x.value,originY:y.value,direction:null,moved:false};e.currentTarget.setPointerCapture?.(e.pointerId)}
function pointerMove(e){if(!gesture||gesture.pointerId!==e.pointerId)return;const dx=e.clientX-gesture.startX,dy=e.clientY-gesture.startY,distance=Math.hypot(dx,dy);gesture.moved=distance>4;if(!gesture.direction&&distance>=6)gesture.direction=Math.abs(dx)>Math.abs(dy)*1.15?'horizontal':Math.abs(dy)>Math.abs(dx)*1.15?'vertical':null;if(!gesture.direction)return;dragging.value=true;document.documentElement.style.cursor='grabbing';const now=performance.now(),elapsed=Math.max(1,now-gesture.lastTime);gesture.velocityX=(e.clientX-gesture.lastX)/elapsed;gesture.lastX=e.clientX;gesture.lastTime=now;e.preventDefault();const bounds=panBounds();if(gesture.direction==='vertical'){y.value=resist(gesture.originY+dy,bounds.y);return}if(scale.value>1){x.value=resist(gesture.originX+dx,bounds.x)}else{const available=dx>0?Boolean(props.viewer.previous_url):Boolean(props.viewer.next_url);x.value=available?dx:dx*.22}}
function settle(targetX,targetY,callback){animating.value=true;x.value=targetX;y.value=targetY;gestureAnimationTimer=setTimeout(()=>{gestureAnimationTimer=null;animating.value=false;callback?.()},window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:180)}
function pointerUp(e){if(!gesture||gesture.pointerId!==e.pointerId)return;const state=gesture,dx=e.clientX-state.startX;gesture=null;if(state.target?.hasPointerCapture?.(state.pointerId))try{state.target.releasePointerCapture(state.pointerId)}catch{}dragging.value=false;document.documentElement.style.removeProperty('cursor');suppressClick=state.moved;const bounds=panBounds(),validY=clamp(y.value,-bounds.y,bounds.y);if(state.direction==='vertical'){if(validY!==y.value)settle(x.value,validY,()=>{interacting.value=false;scheduleSlideshow()});else{interacting.value=false;scheduleSlideshow()}return}if(scale.value>1){const validX=clamp(x.value,-bounds.x,bounds.x);if(validX!==x.value)settle(validX,validY,()=>{interacting.value=false;scheduleSlideshow()});else{interacting.value=false;scheduleSlideshow()}return}const width=stage.value?.clientWidth||window.innerWidth,threshold=width*.22,fast=Math.abs(state.velocityX)>=.55&&Math.abs(dx)>=24,target=dx>0?props.viewer.previous_url:props.viewer.next_url,shouldNavigate=state.direction==='horizontal'&&Boolean(target)&&(Math.abs(dx)>=threshold||fast);if(shouldNavigate){settle(dx>0?width:-width,y.value,()=>{x.value=0;y.value=0;interacting.value=false;navigate(target)})}else{settle(0,validY,()=>{interacting.value=false;scheduleSlideshow()})}}
function pointerCancel(e){if(!gesture||gesture.pointerId!==e.pointerId)return;gesture=null;dragging.value=false;document.documentElement.style.removeProperty('cursor');const bounds=panBounds();settle(scale.value>1?clamp(x.value,-bounds.x,bounds.x):0,clamp(y.value,-bounds.y,bounds.y),()=>{interacting.value=false;scheduleSlideshow()})}
function tap(){if(suppressClick){suppressClick=false;return}const now=Date.now();if(now-lastTap<300)scale.value>1?reset():zoom(1);else controls.value=!controls.value;lastTap=now}
