<div v-if="viewer.previous_url" class="viewer-nav-zone viewer-nav-zone--previous"><button type="button" class="viewer-nav" aria-label="Previous photo" title="Previous photo" @pointerdown.stop @click.stop.prevent="navigate(viewer.previous_url)"><span aria-hidden="true">‹</span></button></div><div v-if="viewer.next_url" class="viewer-nav-zone viewer-nav-zone--next"><button type="button" class="viewer-nav" aria-label="Next photo" title="Next photo" @pointerdown.stop @click.stop.prevent="navigate(viewer.next_url)"><span aria-hidden="true">›</span></button></div>
