<aside :class="['viewer-tools viewer-tools--bottom hidden transition-opacity sm:flex',controls?'opacity-100':'pointer-events-none opacity-0']" aria-label="Photo actions"><button v-if="photo.download_url" type="button" class="viewer-control" aria-label="Download photo" title="Download photo" :disabled="downloading" @pointerdown.stop @click.stop.prevent="downloadCurrentPhoto"><svg aria-hidden="true" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5"/><path d="M12 15V3"/></svg></button><button v-if="event.can_share_group" type="button" class="viewer-control" aria-label="Share Group" title="Share Group" :disabled="sharing" @pointerdown.stop @click.stop="shareCurrentGroup"><span v-if="sharing">…</span><svg v-else aria-hidden="true" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.5 6.8-4"/><path d="m8.6 13.5 6.8 4"/></svg></button><button v-if="event.favourites_enabled" type="button" :class="['viewer-control',photo.liked?'text-rose-400':'']" :aria-label="photo.liked?'Remove from favourites':'Add to favourites'" :title="photo.liked?'Remove from favourites':'Add to favourites'" :aria-pressed="photo.liked" @pointerdown.stop @click.stop="favourite">{{photo.liked?'♥':'♡'}}</button><button type="button" class="viewer-control" aria-label="Photo settings" title="Photo settings" @pointerdown.stop @click.stop="infoOpen=!infoOpen"><svg aria-hidden="true" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.